	for (const g of bump(s.goals, c.goals && settleKeys(s.goals, c.goals))) {
		const i = byId.get(g.id);
		if (i == null) {
			byId.set(g.id, goals.length);
			goals.push(g);
		} else goals[i] = g;
	}
